CREATE TABLE IF NOT EXISTS consumer_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, plan varchar(40) NOT NULL, status subscription_status NOT NULL DEFAULT 'trialing', locked_price_minor integer NOT NULL, currency varchar(3) NOT NULL DEFAULT 'KES', billing_interval varchar(16) NOT NULL, current_period_start timestamptz NOT NULL, current_period_end timestamptz NOT NULL, cancel_at_period_end boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS consumer_memberships_status_period_idx ON consumer_memberships(status,current_period_end);
ALTER TABLE payments ADD COLUMN IF NOT EXISTS consumer_subscription_id uuid REFERENCES consumer_memberships(id) ON DELETE SET NULL;
